INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch13$PT144-S4-Q2$batch13$, 144, 4, 2, $batch13$Principle$batch13$, $batch13$Wanda: It is common sense that one cannot create visual art without visual stimuli in one’s work area, just as a writer needs written stimuli. A stark, empty work area would hinder my creativity. This is why there are so many things in my studio.
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$A$batch13$, $batch13$It is unhealthy to work in a cluttered work area.$batch13$, $batch13$Unsupported$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT144-S4-Q2$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$A$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$B$batch13$, $batch13$The quality of the stimuli in an artist’s environment matters.$batch13$, $batch13$Correct$batch13$, true FROM lr_questions q WHERE q.qid=$batch13$PT144-S4-Q2$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$B$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$C$batch13$, $batch13$Supermarket tabloids should not be considered stimulating.$batch13$, $batch13$Too Narrow$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT144-S4-Q2$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$C$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$D$batch13$, $batch13$Messiness impairs artistic creativity.$batch13$, $batch13$Too Strong$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT144-S4-Q2$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$D$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$E$batch13$, $batch13$One should be able to be creative even in a stark, empty work area.$batch13$, $batch13$Opposite$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT144-S4-Q2$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$E$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch13$PT144-S4-Q2$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch13$Wanda$batch13$, $batch13$Visual art needs visual stimuli, just as writers need written stimuli. That's why Wanda's studio is full of things.$batch13$), (1, $batch13$Vernon$batch13$, $batch13$Writers need good writing, not tabloids. Are piles of laundry and empty soda bottles inspiring?$batch13$), (2, $batch13$Evaluate$batch13$, $batch13$Vernon doesn't deny that artists need stimuli. Vernon questions the kind. Tabloids and laundry are stimuli, but poor ones. The principle is that quality matters, not just having something around.$batch13$), (3, $batch13$Goal$batch13$, $batch13$The quality of an artist's stimuli matters.$batch13$)) v(position,label,body) WHERE q.qid=$batch13$PT144-S4-Q2$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch13$A$batch13$, $batch13$Vernon says nothing about health.$batch13$), ($batch13$B$batch13$, $batch13$Good writing versus tabloids and art versus laundry both make the same point: what you surround yourself with matters.$batch13$), ($batch13$C$batch13$, $batch13$Tabloids are one example. The principle covers all stimuli.$batch13$), ($batch13$D$batch13$, $batch13$Vernon doesn't say mess hurts creativity, only that junk may not inspire.$batch13$), ($batch13$E$batch13$, $batch13$Vernon never defends an empty work area.$batch13$)) v(letter,body) WHERE q.qid=$batch13$PT144-S4-Q2$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
